CREATE TABLE IF NOT EXISTS app_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS map_labels (id TEXT PRIMARY KEY, map_id TEXT NOT NULL REFERENCES maps(id) ON DELETE CASCADE, name TEXT NOT NULL, source_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS map_render_configs (map_id TEXT PRIMARY KEY REFERENCES maps(id) ON DELETE CASCADE, transform_json TEXT NOT NULL, rotation REAL NOT NULL DEFAULT 0, bounds_json TEXT NOT NULL, svg_uri TEXT, cached_asset_path TEXT, attribution TEXT, license TEXT, validated INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS map_floor_layers (map_id TEXT NOT NULL REFERENCES maps(id) ON DELETE CASCADE, layer_id TEXT NOT NULL, name TEXT NOT NULL, min_height REAL NOT NULL, max_height REAL NOT NULL, asset_reference TEXT, PRIMARY KEY (map_id, layer_id));
CREATE TABLE IF NOT EXISTS item_icon_fingerprints (item_id TEXT NOT NULL REFERENCES items(id) ON DELETE CASCADE, hash_type TEXT NOT NULL, hash TEXT NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, updated_utc TEXT NOT NULL, PRIMARY KEY (item_id, hash_type, width, height));
CREATE TABLE IF NOT EXISTS profile_trader_levels (profile_id TEXT NOT NULL REFERENCES player_profiles(id) ON DELETE CASCADE, trader_id TEXT NOT NULL, level INTEGER NOT NULL, PRIMARY KEY (profile_id, trader_id));
CREATE TABLE IF NOT EXISTS profile_hideout_progress (profile_id TEXT NOT NULL REFERENCES player_profiles(id) ON DELETE CASCADE, station_id TEXT NOT NULL, level INTEGER NOT NULL, PRIMARY KEY (profile_id, station_id));
CREATE TABLE IF NOT EXISTS profile_wishlist (profile_id TEXT NOT NULL REFERENCES player_profiles(id) ON DELETE CASCADE, item_id TEXT NOT NULL, PRIMARY KEY (profile_id, item_id));
CREATE TABLE IF NOT EXISTS profile_item_counts (profile_id TEXT NOT NULL REFERENCES player_profiles(id) ON DELETE CASCADE, item_id TEXT NOT NULL, count INTEGER NOT NULL, PRIMARY KEY (profile_id, item_id));
CREATE TABLE IF NOT EXISTS profile_overrides (profile_id TEXT NOT NULL REFERENCES player_profiles(id) ON DELETE CASCADE, item_id TEXT NOT NULL, action TEXT NOT NULL, note TEXT, PRIMARY KEY (profile_id, item_id));
CREATE TABLE IF NOT EXISTS event_definitions (event_id TEXT PRIMARY KEY, name TEXT NOT NULL, start_utc TEXT, end_utc TEXT, rules_json TEXT NOT NULL, active INTEGER NOT NULL, source_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS event_items (event_id TEXT NOT NULL REFERENCES event_definitions(event_id) ON DELETE CASCADE, item_id TEXT NOT NULL, metadata_json TEXT, PRIMARY KEY (event_id, item_id));
CREATE TABLE IF NOT EXISTS profile_event_item_state (profile_id TEXT NOT NULL REFERENCES player_profiles(id) ON DELETE CASCADE, event_id TEXT NOT NULL REFERENCES event_definitions(event_id) ON DELETE CASCADE, item_id TEXT NOT NULL, state TEXT NOT NULL, updated_utc TEXT NOT NULL, PRIMARY KEY (profile_id, event_id, item_id));
CREATE TABLE IF NOT EXISTS key_intelligence_overrides (key_item_id TEXT PRIMARY KEY, score_json TEXT NOT NULL, notes TEXT NOT NULL, source TEXT NOT NULL, source_date TEXT NOT NULL, confidence REAL NOT NULL);
CREATE TABLE IF NOT EXISTS raid_positions (id INTEGER PRIMARY KEY AUTOINCREMENT, raid_id TEXT NOT NULL REFERENCES raids(id) ON DELETE CASCADE, timestamp_utc TEXT NOT NULL, x REAL NOT NULL, y REAL NOT NULL, z REAL NOT NULL, heading REAL NOT NULL, floor TEXT, screenshot_filename TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS raid_extracts (raid_id TEXT NOT NULL REFERENCES raids(id) ON DELETE CASCADE, extract_id TEXT NOT NULL, name TEXT NOT NULL, confidence REAL NOT NULL, source TEXT NOT NULL, PRIMARY KEY (raid_id, extract_id));
